package edu.example.ledger;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrowsExactly;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.junit.jupiter.params.provider.ValueSource;

/** Tests generated by the AI. */
class FineLedgerTest {

    private FineLedger ledger;

    @BeforeEach
    void setUp() {
        ledger = new FineLedger();
    }

    @Test
    void addFineIncreasesOwed() {
        ledger.addFine("S1", 300);
        ledger.addFine("S1", 200);
        assertEquals(500, ledger.owed("S1"));
    }

    @Test
    void zeroFineIsRejectedWithoutChangingBalance() {
        ledger.addFine("S1", 500);
        assertThrowsExactly(IllegalArgumentException.class, () -> ledger.addFine("S1", 0));
        assertEquals(500, ledger.owed("S1"));
        assertEquals(List.of("S1"), ledger.debtors());
    }

    @ParameterizedTest
    @ValueSource(ints = {1, 100000})
    void singleFineBoundariesAreAccepted(int cents) {
        ledger.addFine("S1", cents);
        assertEquals(cents, ledger.owed("S1"));
    }

    @ParameterizedTest
    @ValueSource(ints = {-1, 100001})
    void invalidFineAmountPreservesBalance(int cents) {
        ledger.addFine("S1", 500);
        assertThrowsExactly(IllegalArgumentException.class, () -> ledger.addFine("S1", cents));
        assertEquals(500, ledger.owed("S1"));
    }

    @Test
    void accumulatedFineOverflowIsRejectedWithoutChangingBalance() {
        for (int i = 0; i < 21474; i++) {
            ledger.addFine("S1", 100000);
        }
        ledger.addFine("S1", 83647);
        assertEquals(Integer.MAX_VALUE, ledger.owed("S1"));

        assertThrowsExactly(IllegalArgumentException.class, () -> ledger.addFine("S1", 1));
        assertEquals(Integer.MAX_VALUE, ledger.owed("S1"));
        assertTrue(ledger.isBlocked("S1"));
        assertEquals(List.of("S1"), ledger.debtors());

        assertEquals(Integer.MAX_VALUE - 1, ledger.pay("S1", 1));
        ledger.addFine("S1", 1);
        assertEquals(Integer.MAX_VALUE, ledger.owed("S1"));
    }

    @Test
    void payReducesOwed() {
        ledger.addFine("S1", 500);
        assertEquals(200, ledger.pay("S1", 300));
        assertEquals(200, ledger.owed("S1"));
    }

    @Test
    void overpaymentIsRejectedWithoutChangingBalance() {
        ledger.addFine("S1", 500);
        assertThrowsExactly(IllegalArgumentException.class, () -> ledger.pay("S1", 600));
        assertEquals(500, ledger.owed("S1"));
        assertEquals(List.of("S1"), ledger.debtors());
    }

    @Test
    void fullPaymentRemovesStudentFromDebtors() {
        ledger.addFine("S1", 500);
        assertEquals(0, ledger.pay("S1", 500));
        assertEquals(0, ledger.owed("S1"));
        assertEquals(List.of(), ledger.debtors());
    }

    @Test
    void unrecordedStudentOwesNothing() {
        assertEquals(0, ledger.owed("S9"));
        assertEquals(List.of(), ledger.debtors());
    }

    @Test
    void studentOwingALotIsBlocked() {
        ledger.addFine("S1", 5_000);
        assertTrue(ledger.isBlocked("S1"));
    }

    @ParameterizedTest
    @CsvSource({"999,false", "1000,true", "1001,true"})
    void blockingThresholdIncludesEquality(int cents, boolean expected) {
        ledger.addFine("S1", cents);
        assertEquals(expected, ledger.isBlocked("S1"));
    }

    @Test
    void debtorsSortedByAmount() {
        ledger.addFine("S1", 100);
        ledger.addFine("S2", 900);
        ledger.addFine("S3", 500);
        assertEquals(List.of("S2", "S3", "S1"), ledger.debtors());
    }

    @Test
    void equalDebtsAreOrderedByStudentIdAscending() {
        ledger.addFine("S1", 300);
        ledger.addFine("S2", 900);
        ledger.addFine("S3", 300);
        assertEquals(List.of("S2", "S1", "S3"), ledger.debtors());
    }

    @Test
    void debtorListIsUnmodifiableAndLedgerIsUnchanged() {
        ledger.addFine("S1", 500);
        List<String> debtors = ledger.debtors();
        assertThrowsExactly(UnsupportedOperationException.class, debtors::clear);
        assertEquals(List.of("S1"), debtors);
        assertEquals(500, ledger.owed("S1"));
        assertEquals(List.of("S1"), ledger.debtors());
    }
}
